module.exports = [
{ e: "🌴", art: { b: "🌴", s: ["🌿", "🌸", "☀️", "🌋"], c: ["#1B4E2A", "#4AA05A"] },
pt: { h: "Leo desenhou um T. rex correndo num gramado verdinho. O vovô sorriu e contou um segredo: “Durante quase toda a época dos dinossauros, não existia grama!” Nina não acreditou. “Também quase não tinha flores no começo”, disse ele. “Era um mundo de samambaias e pinheiros.”", t: "O mundo dos dinossauros", f: "No tempo dos dinossauros, a Terra era mais quente, os polos quase não tinham gelo e o mar era mais alto. As plantas mais comuns eram samambaias, cavalinhas, pinheiros e cicas, parecidas com palmeiras. As flores só apareceram no Cretáceo, e a grama surgiu bem no finalzinho.", x: "Algumas plantas daquela época existem até hoje quase iguais, como as samambaias, as cavalinhas e o ginkgo. São verdadeiros fósseis vivos!", s: ["Os continentes estavam em lugares diferentes, e o clima mudou muito durante os milhões de anos dos dinossauros.", "As abelhas e as flores evoluíram juntas, ajudando umas às outras.", "Os dinossauros herbívoros comiam muitas samambaias e folhas de pinheiro."], ex: { t: "Impressão de esporos", m: "uma folha madura de samambaia (com pontinhos marrons embaixo) ou um cogumelo de mercado, papel branco, um copo", p: ["Coloque a folha de samambaia com os pontinhos virados para baixo sobre o papel (ou o chapéu do cogumelo virado para baixo).", "Cubra com um copo e deixe parado de um dia para o outro.", "Retire com cuidado: ficou um desenho de pó! São os esporos, a forma antiga de as samambaias se espalharem, muito antes das sementes e das flores."] }, at: "Ficha da paisagem jurássica", m: "papel, lápis de cor, folhas secas (opcional)", p: ["Desenhe uma paisagem do tempo dos dinossauros, só com plantas daquela época: samambaias, pinheiros e cicas.", "Lembre: nada de grama!", "Cole folhas secas de verdade, se tiver, e coloque a ficha no museu."], q: "Como seria o mundo hoje sem flores e sem grama?" },
en: { h: "Leo drew a T. rex running across a bright green lawn. Grandpa smiled and shared a secret: “For almost the whole dinosaur age, there was no grass!” Nina didn't believe it. “There were hardly any flowers at first either,” he said. “It was a world of ferns and pine trees.”", t: "The dinosaurs' world", f: "In dinosaur times, Earth was warmer, the poles had almost no ice and sea levels were higher. The most common plants were ferns, horsetails, conifers and cycads, which look like palm trees. Flowers only appeared in the Cretaceous, and grass showed up right at the very end.", x: "Some plants from back then still exist almost unchanged today, like ferns, horsetails and ginkgo. They're true living fossils!", s: ["The continents were in different places, and the climate changed a lot over the millions of years of the dinosaurs.", "Bees and flowers evolved together, helping each other.", "Plant-eating dinosaurs ate lots of ferns and conifer needles."], ex: { t: "Spore print", m: "a mature fern frond (with brown dots underneath) or a store-bought mushroom, white paper, a glass", p: ["Lay the fern frond dots-down on the paper (or the mushroom cap gills-down).", "Cover it with a glass and leave it overnight.", "Lift it off carefully: a powder picture is left behind! Those are spores, the ancient way ferns spread, long before seeds and flowers."] }, at: "Jurassic landscape card", m: "paper, colored pencils, dry leaves (optional)", p: ["Draw a dinosaur-age landscape with only plants from that time: ferns, conifers and cycads.", "Remember: no grass!", "Glue on real dry leaves if you have some, and put the card in the museum."], q: "What would the world be like today without flowers or grass?" },
es: { h: "Leo dibujó un T. rex corriendo por un pasto verdecito. El abuelo sonrió y le contó un secreto: “¡Durante casi toda la época de los dinosaurios no existía el pasto!” Nina no le creyó. “Al principio tampoco había casi flores”, dijo él. “Era un mundo de helechos y pinos.”", t: "El mundo de los dinosaurios", f: "En la época de los dinosaurios, la Tierra era más cálida, los polos casi no tenían hielo y el mar estaba más alto. Las plantas más comunes eran helechos, colas de caballo, pinos y cícadas, parecidas a palmeras. Las flores aparecieron recién en el Cretácico, y el pasto surgió justo al final.", x: "¡Algunas plantas de esa época existen hasta hoy casi iguales, como los helechos, las colas de caballo y el ginkgo! Son verdaderos fósiles vivientes.", s: ["Los continentes estaban en lugares diferentes, y el clima cambió mucho durante los millones de años de los dinosaurios.", "Las abejas y las flores evolucionaron juntas, ayudándose entre sí.", "Los dinosaurios herbívoros comían muchos helechos y hojas de pino."], ex: { t: "Impresión de esporas", m: "una hoja madura de helecho (con puntitos marrones debajo) o un hongo de verdulería, papel blanco, un vaso", p: ["Pon la hoja de helecho con los puntitos hacia abajo sobre el papel (o el sombrero del hongo hacia abajo).", "Cúbrela con un vaso y déjala quieta de un día para el otro.", "Retírala con cuidado: ¡quedó un dibujo de polvo! Son las esporas, la forma antigua en que se reproducen los helechos, mucho antes de las semillas y las flores."] }, at: "Ficha del paisaje jurásico", m: "papel, lápices de colores, hojas secas (opcional)", p: ["Dibuja un paisaje de la época de los dinosaurios, solo con plantas de entonces: helechos, pinos y cícadas.", "Recuerda: ¡nada de pasto!", "Pega hojas secas de verdad, si tienes, y pon la ficha en el museo."], q: "¿Cómo sería el mundo hoy sin flores y sin pasto?" } },

{ e: "☄️", art: { b: "☄️", s: ["💥", "🌋", "🌑", "🦖"], c: ["#2A0B0B", "#C2402C"] },
pt: { h: "Nina perguntou o que tinha acontecido com os dinossauros gigantes. O vovô apagou as luzes, acendeu a lanterna e falou devagar: “Há 66 milhões de anos, uma pedra enorme veio do espaço…” Leo segurou a mão da irmã. Depois, o vovô pegou farinha e chocolate em pó para mostrar a cratera.", t: "O dia em que o céu caiu", f: "Há uns 66 milhões de anos, um asteroide de uns 10 quilômetros de largura caiu onde hoje é o México. O impacto levantou poeira, fumaça e fogo, escureceu o céu por muito tempo e esfriou o planeta. Sem luz, as plantas morreram, e depois os animais que dependiam delas.", x: "A cratera do impacto, chamada Chicxulub, tem cerca de 180 quilômetros de largura e hoje está escondida debaixo da terra e do mar, no México!", s: ["Cerca de três quartos de todas as espécies do planeta desapareceram nessa época.", "Os cientistas acharam pistas no mundo todo: uma camada fina de rocha cheia de um metal raro que vem do espaço.", "Muitos cientistas acham que grandes erupções de vulcões na Índia também ajudaram a mudar o clima naquela época."], ex: { t: "Crateras de farinha", m: "uma bandeja funda, farinha de trigo, chocolate em pó, bolinhas de gude ou pedrinhas de tamanhos diferentes", p: ["Espalhe uma camada grossa de farinha na bandeja e polvilhe chocolate em pó por cima.", "Solte as bolinhas de alturas diferentes em cima da farinha.", "Observe as crateras: quanto mais pesada e mais alta a queda, maior a cratera, e a farinha branca de baixo espirra por cima!"] }, at: "Ficha do fim de uma era", m: "papel, lápis de cor", p: ["Desenhe a cena em dois quadros: antes, com dinossauros e céu azul; e depois, com o céu escuro.", "Escreva: “66 milhões de anos atrás”.", "Coloque a ficha no museu, numa sala especial."], q: "Se você fosse um cientista, como estudaria um acontecimento de tanto tempo atrás?" },
en: { h: "Nina asked what happened to the giant dinosaurs. Grandpa turned off the lights, switched on the flashlight and spoke slowly: “Sixty-six million years ago, a huge rock came from space…” Leo held his sister's hand. Then Grandpa got out flour and cocoa powder to show them the crater.", t: "The day the sky fell", f: "About 66 million years ago, an asteroid around 10 kilometers (6 miles) wide crashed into what is now Mexico. The impact threw up dust, smoke and fire, darkened the sky for a long time and cooled the planet. Without light, plants died, and then the animals that depended on them.", x: "The impact crater, called Chicxulub, is about 180 kilometers (110 miles) wide and is now hidden under land and sea in Mexico!", s: ["About three-quarters of all species on the planet disappeared at that time.", "Scientists found clues all over the world: a thin layer of rock full of a rare metal that comes from space.", "Many scientists think huge volcanic eruptions in India also helped change the climate at that time."], ex: { t: "Flour craters", m: "a deep tray, flour, cocoa powder, marbles or pebbles of different sizes", p: ["Spread a thick layer of flour in the tray and dust cocoa powder on top.", "Drop the marbles from different heights onto the flour.", "Look at the craters: the heavier and higher the drop, the bigger the crater, and the white flour underneath splashes up on top!"] }, at: "End of an era card", m: "paper, colored pencils", p: ["Draw the scene in two panels: before, with dinosaurs and a blue sky; and after, with a dark sky.", "Write: “66 million years ago.”", "Put the card in the museum, in a special room."], q: "If you were a scientist, how would you study something that happened so long ago?" },
es: { h: "Nina preguntó qué les pasó a los dinosaurios gigantes. El abuelo apagó las luces, encendió la linterna y habló despacio: “Hace 66 millones de años, una piedra enorme vino del espacio…” Leo le tomó la mano a su hermana. Después, el abuelo sacó harina y cacao en polvo para mostrarles el cráter.", t: "El día en que cayó el cielo", f: "Hace unos 66 millones de años, un asteroide de unos 10 kilómetros de ancho cayó donde hoy está México. El impacto levantó polvo, humo y fuego, oscureció el cielo durante mucho tiempo y enfrió el planeta. Sin luz, las plantas murieron, y después los animales que dependían de ellas.", x: "¡El cráter del impacto, llamado Chicxulub, mide unos 180 kilómetros de ancho y hoy está escondido bajo la tierra y el mar, en México!", s: ["Cerca de tres cuartas partes de todas las especies del planeta desaparecieron en esa época.", "Los científicos encontraron pistas en todo el mundo: una capa fina de roca llena de un metal raro que viene del espacio.", "Muchos científicos creen que grandes erupciones de volcanes en la India también ayudaron a cambiar el clima en esa época."], ex: { t: "Cráteres de harina", m: "una bandeja honda, harina, cacao en polvo, canicas o piedritas de distintos tamaños", p: ["Esparce una capa gruesa de harina en la bandeja y espolvorea cacao encima.", "Suelta las canicas desde distintas alturas sobre la harina.", "Observa los cráteres: cuanto más pesada y más alta la caída, más grande el cráter, ¡y la harina blanca de abajo salpica por encima!"] }, at: "Ficha del fin de una era", m: "papel, lápices de colores", p: ["Dibuja la escena en dos cuadros: antes, con dinosaurios y cielo azul; y después, con el cielo oscuro.", "Escribe: “Hace 66 millones de años”.", "Pon la ficha en el museo, en una sala especial."], q: "Si fueras científico, ¿cómo estudiarías algo que pasó hace tanto tiempo?" } },

{ e: "🐢", art: { b: "🐢", s: ["🐊", "🐦", "🐭", "🦈"], c: ["#1B3A2A", "#4A8A5A"] },
pt: { h: "Leo ficou triste por todos os bichos que desapareceram com o asteroide. O vovô colocou no sofá um passarinho de pelúcia, um jacaré de brinquedo, uma tartaruga e um ratinho. “Mas estes sobreviveram!”, disse. “E graças a eles, hoje existimos nós.”", t: "Os sobreviventes", f: "Nem todo mundo desapareceu há 66 milhões de anos. Sobreviveram aves, crocodilos, tartarugas, lagartos, cobras, sapos, tubarões e pequenos mamíferos. Muitos eram pequenos, comiam de tudo ou podiam se esconder em tocas e na água.", x: "Os mamíferos daquela época eram pequenos, mais ou menos do tamanho de ratos. Sem os grandes dinossauros, eles tiveram espaço para crescer e se espalhar, e milhões de anos depois surgiram os elefantes, as baleias… e os humanos!", s: ["Os crocodilos existem desde antes dos dinossauros gigantes e continuam por aí até hoje.", "Ser pequeno ajudava a sobreviver com pouca comida.", "As tocas debaixo da terra protegiam os animais do calor e do frio extremos."], ex: { t: "Esconderijo na toca", m: "dois cubos de gelo iguais, um vaso ou pote com terra, um lugar ao sol", p: ["Enterre um cubo de gelo na terra, a uns 3 dedos de profundidade.", "Coloque o outro cubo em cima da terra, ao sol.", "Depois de meia hora, desenterre o primeiro. Qual derreteu mais? A terra protege do calor, como as tocas protegeram pequenos animais quando o mundo mudou."] }, at: "Ficha dos sobreviventes", m: "papel, lápis de cor", p: ["Desenhe uma fila com os sobreviventes: ave, crocodilo, tartaruga, lagarto, sapo, tubarão e um pequeno mamífero.", "Embaixo de cada um, escreva o “superpoder” que o ajudou a sobreviver.", "Coloque a ficha no museu."], q: "Que superpoder você acha que mais ajuda um animal a sobreviver?" },
en: { h: "Leo felt sad about all the animals that disappeared with the asteroid. Grandpa set a stuffed bird, a toy alligator, a turtle and a little mouse on the couch. “But these survived!” he said. “And thanks to them, we exist today.”", t: "The survivors", f: "Not everything disappeared 66 million years ago. Birds, crocodiles, turtles, lizards, snakes, frogs, sharks and small mammals survived. Many were small, ate almost anything or could hide in burrows and water.", x: "Mammals back then were small, about the size of mice. Without the big dinosaurs, they had room to grow and spread, and millions of years later came elephants, whales… and humans!", s: ["Crocodiles have been around since before the giant dinosaurs and are still here today.", "Being small helped animals survive on little food.", "Underground burrows protected animals from extreme heat and cold."], ex: { t: "Hiding in a burrow", m: "two identical ice cubes, a pot or container of soil, a sunny spot", p: ["Bury one ice cube in the soil about three fingers deep.", "Put the other cube on top of the soil, in the sun.", "After half an hour, dig up the first one. Which melted more? Soil protects from heat, just as burrows protected small animals when the world changed."] }, at: "Survivors card", m: "paper, colored pencils", p: ["Draw a lineup of survivors: a bird, a crocodile, a turtle, a lizard, a frog, a shark and a small mammal.", "Under each one, write the “superpower” that helped it survive.", "Put the card in the museum."], q: "What superpower do you think helps an animal survive most?" },
es: { h: "Leo se puso triste por todos los animales que desaparecieron con el asteroide. El abuelo puso en el sillón un pajarito de peluche, un yacaré de juguete, una tortuga y un ratoncito. “¡Pero estos sobrevivieron!”, dijo. “Y gracias a ellos, hoy existimos nosotros.”", t: "Los sobrevivientes", f: "No todo desapareció hace 66 millones de años. Sobrevivieron aves, cocodrilos, tortugas, lagartos, serpientes, sapos, tiburones y pequeños mamíferos. Muchos eran pequeños, comían de todo o podían esconderse en madrigueras y en el agua.", x: "¡Los mamíferos de esa época eran pequeños, más o menos del tamaño de ratones! Sin los grandes dinosaurios, tuvieron espacio para crecer y extenderse, y millones de años después aparecieron los elefantes, las ballenas… y los humanos.", s: ["Los cocodrilos existen desde antes de los dinosaurios gigantes y siguen aquí hasta hoy.", "Ser pequeño ayudaba a sobrevivir con poca comida.", "Las madrigueras bajo tierra protegían a los animales del calor y del frío extremos."], ex: { t: "Escondite en la madriguera", m: "dos cubitos de hielo iguales, una maceta o recipiente con tierra, un lugar al sol", p: ["Entierra un cubito de hielo en la tierra, a unos tres dedos de profundidad.", "Pon el otro cubito encima de la tierra, al sol.", "Después de media hora, desentierra el primero. ¿Cuál se derritió más? La tierra protege del calor, como las madrigueras protegieron a los animales pequeños cuando el mundo cambió."] }, at: "Ficha de los sobrevivientes", m: "papel, lápices de colores", p: ["Dibuja una fila con los sobrevivientes: ave, cocodrilo, tortuga, lagarto, sapo, tiburón y un pequeño mamífero.", "Debajo de cada uno, escribe el “superpoder” que lo ayudó a sobrevivir.", "Pon la ficha en el museo."], q: "¿Qué superpoder crees que más ayuda a un animal a sobrevivir?" } },

{ e: "🦥", art: { b: "🦥", s: ["🐯", "🦣", "🦔", "⛰️"], c: ["#4E3A1B", "#A0803A"] },
pt: { h: "O vovô mostrou a foto de uma preguiça do tamanho de um elefante, de pé, comendo folhas de uma árvore. “Esse bicho viveu aqui no Brasil!”, disse. Leo arregalou os olhos: “Uma preguiça gigante?”. “E tatus do tamanho de um carro e tigres-dentes-de-sabre também”, completou ele.", t: "Os gigantes depois dos dinossauros", f: "Depois dos dinossauros, os mamíferos cresceram e se espalharam. Há poucos milhares de anos, o Brasil tinha a megafauna: preguiças gigantes de até 6 metros, gliptodontes, que pareciam tatus do tamanho de um carro pequeno, e tigres-dentes-de-sabre. Muitos desapareceram há uns 10 mil anos.", x: "Esses animais conviveram com os primeiros humanos da América do Sul! Em cavernas de Lagoa Santa, em Minas Gerais, foram encontrados ossos de animais gigantes perto de vestígios de pessoas.", s: ["O cientista dinamarquês Peter Lund estudou as cavernas de Lagoa Santa nos anos 1800 e encontrou milhares de fósseis.", "O Smilodon, um dos tigres-dentes-de-sabre, tinha dentes de uns 25 centímetros.", "As preguiças e os tatus de hoje são parentes pequenininhos desses gigantes."], ex: { t: "Mão de gigante", m: "massinha, uma régua, papel e lápis", p: ["Achate um pedaço grande de massinha e aperte sua mão nela para fazer uma marca.", "Meça o comprimento da sua mão.", "Agora desenhe no papel uma garra de preguiça gigante com uns 30 centímetros, quase o tamanho de uma régua inteira! Compare com a sua mão."] }, at: "Ficha da megafauna", m: "papel, lápis de cor", p: ["Desenhe uma paisagem do Brasil de 10 mil anos atrás com uma preguiça gigante, um gliptodonte e um tigre-dente-de-sabre.", "Desenhe um tatu e uma preguiça de hoje ao lado, pequenininhos, para comparar.", "Coloque a ficha no museu, na sala “Depois dos dinossauros”."], q: "Qual animal gigante do passado você gostaria que existisse hoje?" },
en: { h: "Grandpa showed a picture of a sloth the size of an elephant, standing up and eating leaves from a tree. “This animal lived right here in Brazil!” he said. Leo's eyes went wide: “A giant sloth?” “And car-sized armadillos and saber-toothed cats too,” he added.", t: "The giants after the dinosaurs", f: "After the dinosaurs, mammals grew and spread out. Just a few thousand years ago, Brazil had megafauna: giant ground sloths up to 6 meters (20 feet) long, glyptodonts that looked like armadillos the size of a small car, and saber-toothed cats. Many disappeared about 10,000 years ago.", x: "These animals lived alongside the first humans in South America! In caves at Lagoa Santa, in the Brazilian state of Minas Gerais, bones of giant animals were found near traces of people.", s: ["Danish scientist Peter Lund explored the Lagoa Santa caves in the 1800s and found thousands of fossils.", "Smilodon, one of the saber-toothed cats, had teeth about 25 centimeters (10 inches) long.", "Today's sloths and armadillos are tiny relatives of those giants."], ex: { t: "Giant's hand", m: "play dough, a ruler, paper and pencil", p: ["Flatten a big piece of play dough and press your hand into it to make a print.", "Measure the length of your hand.", "Now draw a giant sloth claw on paper about 30 cm (12 inches) long, almost a whole ruler! Compare it with your hand."] }, at: "Megafauna card", m: "paper, colored pencils", p: ["Draw a Brazilian landscape from 10,000 years ago with a giant ground sloth, a glyptodont and a saber-toothed cat.", "Next to them, draw a tiny modern armadillo and sloth for comparison.", "Put the card in the museum, in the “After the dinosaurs” room."], q: "Which giant animal from the past would you like to exist today?" },
es: { h: "El abuelo mostró la foto de un perezoso del tamaño de un elefante, de pie, comiendo hojas de un árbol. “¡Este animal vivió en Sudamérica!”, dijo. Leo abrió grandes los ojos: “¿Un perezoso gigante?”. “Y también armadillos del tamaño de un auto y tigres dientes de sable”, agregó él.", t: "Los gigantes después de los dinosaurios", f: "Después de los dinosaurios, los mamíferos crecieron y se extendieron. Hace apenas unos miles de años, Sudamérica tenía megafauna: perezosos gigantes de hasta 6 metros, gliptodontes que parecían armadillos del tamaño de un auto pequeño y tigres dientes de sable. Muchos desaparecieron hace unos 10.000 años.", x: "¡Estos animales convivieron con los primeros humanos de América del Sur! En cuevas de Lagoa Santa, en Brasil, se encontraron huesos de animales gigantes cerca de rastros de personas.", s: ["El científico danés Peter Lund estudió las cuevas de Lagoa Santa en el siglo XIX y encontró miles de fósiles.", "El Smilodon, uno de los tigres dientes de sable, tenía dientes de unos 25 centímetros.", "Los perezosos y armadillos de hoy son parientes chiquititos de esos gigantes."], ex: { t: "Mano de gigante", m: "plastilina, una regla, papel y lápiz", p: ["Aplasta un pedazo grande de plastilina y aprieta tu mano para dejar la marca.", "Mide el largo de tu mano.", "Ahora dibuja en el papel una garra de perezoso gigante de unos 30 centímetros, ¡casi una regla entera! Compárala con tu mano."] }, at: "Ficha de la megafauna", m: "papel, lápices de colores", p: ["Dibuja un paisaje de Sudamérica de hace 10.000 años con un perezoso gigante, un gliptodonte y un tigre dientes de sable.", "Al lado, dibuja un armadillo y un perezoso de hoy, chiquititos, para comparar.", "Pon la ficha en el museo, en la sala “Después de los dinosaurios”."], q: "¿Qué animal gigante del pasado te gustaría que existiera hoy?" } },

{ e: "🔤", art: { b: "🔤", s: ["🦖", "📚", "✏️", "🏷️"], c: ["#2A1B4E", "#6A4AA0"] },
pt: { h: "Leo queria saber por que os nomes dos dinossauros eram tão difíceis. O vovô escreveu “Tricerátops” num papel e separou em pedaços: “Tri quer dizer três, cerat quer dizer chifre, e ops quer dizer cara. Cara com três chifres!” Nina já queria inventar o nome de um dinossauro novo.", t: "Como nascem os nomes", f: "Quem descobre uma espécie nova escolhe o nome dela, normalmente juntando palavras do grego e do latim que descrevem o animal, o lugar onde foi achado ou uma pessoa homenageada. O nome científico tem duas partes, como Tyrannosaurus rex.", x: "O Irritator challengeri, do Brasil, tem esse sobrenome em homenagem ao Professor Challenger, um personagem de um livro de aventura sobre um mundo perdido com dinossauros!", s: ["Saurus quer dizer lagarto, e raptor quer dizer ladrão.", "Muitos nomes homenageiam lugares, como o Argentinossauro, da Argentina.", "Alguns dinossauros ganham nomes de povos indígenas, cientistas ou até de pessoas famosas."], ex: { t: "Fábrica de nomes", m: "cartões de papel, caneta", p: ["Escreva pedaços de nomes em cartões: tri (três), mega (grande), micro (pequeno), cerat (chifre), dont (dente), saurus (lagarto), raptor (ladrão), ptero (asa).", "Misture os cartões e sorteie dois ou três para formar um nome.", "Leia o nome e descubra o que ele significa. Que tipo de dinossauro seria um “Megadontesaurus”?"] }, at: "Ficha da espécie nova", m: "papel, lápis de cor", p: ["Invente uma espécie nova de dinossauro e dê um nome científico com duas partes.", "Desenhe o dinossauro e escreva o que o nome significa e onde ele foi “encontrado”.", "Coloque a ficha no museu com o seu nome como descobridor!"], q: "Que nome você daria a um dinossauro em sua homenagem?" },
en: { h: "Leo wanted to know why dinosaur names were so hard. Grandpa wrote “Triceratops” on a piece of paper and split it up: “Tri means three, cerat means horn and ops means face. Three-horned face!” Nina already wanted to invent a new dinosaur's name.", t: "How names are born", f: "Whoever discovers a new species chooses its name, usually combining Greek and Latin words that describe the animal, where it was found or a person being honored. A scientific name has two parts, like Tyrannosaurus rex.", x: "Brazil's Irritator challengeri has that second name in honor of Professor Challenger, a character in an adventure novel about a lost world full of dinosaurs!", s: ["Saurus means lizard, and raptor means thief.", "Many names honor places, like Argentinosaurus, from Argentina.", "Some dinosaurs are named after Indigenous peoples, scientists or even famous people."], ex: { t: "Name factory", m: "paper cards, a pen", p: ["Write name pieces on cards: tri (three), mega (big), micro (small), cerat (horn), dont (tooth), saurus (lizard), raptor (thief), ptero (wing).", "Shuffle the cards and draw two or three to build a name.", "Read the name and figure out what it means. What kind of dinosaur would a “Megadontosaurus” be?"] }, at: "New species card", m: "paper, colored pencils", p: ["Invent a new dinosaur species and give it a two-part scientific name.", "Draw the dinosaur and write what its name means and where it was “found.”", "Put the card in the museum with your name as the discoverer!"], q: "What name would you give a dinosaur named after you?" },
es: { h: "Leo quería saber por qué los nombres de los dinosaurios eran tan difíciles. El abuelo escribió “Tricerátops” en un papel y lo separó en pedazos: “Tri quiere decir tres, cerat quiere decir cuerno y ops quiere decir cara. ¡Cara con tres cuernos!” Nina ya quería inventar el nombre de un dinosaurio nuevo.", t: "Cómo nacen los nombres", f: "Quien descubre una especie nueva elige su nombre, normalmente juntando palabras del griego y del latín que describen al animal, el lugar donde se encontró o a una persona homenajeada. El nombre científico tiene dos partes, como Tyrannosaurus rex.", x: "¡El Irritator challengeri, de Brasil, tiene ese apellido en honor al Profesor Challenger, un personaje de una novela de aventuras sobre un mundo perdido lleno de dinosaurios!", s: ["Saurus quiere decir lagarto, y raptor quiere decir ladrón.", "Muchos nombres homenajean lugares, como el Argentinosaurio, de Argentina.", "Algunos dinosaurios reciben nombres de pueblos indígenas, científicos o incluso personas famosas."], ex: { t: "Fábrica de nombres", m: "tarjetas de papel, bolígrafo", p: ["Escribe pedazos de nombres en tarjetas: tri (tres), mega (grande), micro (pequeño), cerat (cuerno), dont (diente), saurus (lagarto), raptor (ladrón), ptero (ala).", "Mezcla las tarjetas y saca dos o tres para formar un nombre.", "Lee el nombre y descubre qué significa. ¿Qué tipo de dinosaurio sería un “Megadontosaurus”?"] }, at: "Ficha de la especie nueva", m: "papel, lápices de colores", p: ["Inventa una especie nueva de dinosaurio y ponle un nombre científico de dos partes.", "Dibuja el dinosaurio y escribe qué significa el nombre y dónde fue “encontrado”.", "¡Pon la ficha en el museo con tu nombre como descubridor!"], q: "¿Qué nombre le pondrías a un dinosaurio en tu honor?" } },

{ e: "❓", art: { b: "❓", s: ["🦕", "🔍", "✅", "❌"], c: ["#3A1B1B", "#9A4A4A"] },
pt: { h: "Na hora do lanche, Leo afirmou com certeza: “Os homens das cavernas andavam montados em dinossauros!”. Nina riu, e o vovô aproveitou: “Hoje vamos brincar de caçar mitos. Até os cientistas já erraram feio sobre dinossauros… e corrigir os erros faz parte da ciência!”", t: "Mitos e erros sobre dinossauros", f: "Ao longo do tempo, muita gente teve ideias erradas sobre os dinossauros. Os cientistas também erram, mas quando encontram novas provas, eles corrigem o que pensavam. É assim que a ciência funciona: testando, revisando e aprendendo sempre.", x: "Quando o Iguanodonte foi descoberto, nos anos 1800, os cientistas colocaram um espinho no nariz dele. Mais tarde descobriram que o espinho ficava no polegar!", s: ["Mito: humanos e dinossauros gigantes viveram juntos. Verdade: entre eles passaram mais de 60 milhões de anos.", "Mito: todos os dinossauros eram enormes. Verdade: muitos eram do tamanho de galinhas.", "Mito: dá para clonar um dinossauro com DNA de um mosquito no âmbar. Verdade: o DNA não dura tantos milhões de anos."], ex: { t: "Telefone sem fio da ciência", m: "um grupo de pessoas, uma frase sobre dinossauros escrita num papel", p: ["A primeira pessoa lê a frase e cochicha no ouvido da próxima, que passa adiante, até o fim da fila.", "A última pessoa fala em voz alta o que ouviu. Comparem com o papel!", "A frase mudou? Os cientistas sempre voltam à prova original, os fósseis, para conferir se a história está certa."] }, at: "Ficha mito ou verdade", m: "papel, lápis de cor", p: ["Faça duas colunas: Mito e Verdade.", "Escreva três mitos sobre dinossauros e a verdade de cada um.", "Desafie a família a acertar qual é qual e coloque a ficha no museu."], q: "Você já mudou de ideia depois de aprender algo novo? Sobre o quê?" },
en: { h: "At snack time, Leo declared confidently, “Cavemen rode around on dinosaurs!” Nina laughed, and Grandpa seized the moment: “Today we'll go myth hunting. Even scientists have gotten dinosaurs badly wrong… and fixing mistakes is part of science!”", t: "Dinosaur myths and mistakes", f: "Over time, lots of people had wrong ideas about dinosaurs. Scientists make mistakes too, but when they find new evidence, they correct what they thought. That's how science works: testing, revising and always learning.", x: "When Iguanodon was discovered in the 1800s, scientists put a spike on its nose. Later they found out the spike belonged on its thumb!", s: ["Myth: humans and giant dinosaurs lived together. Truth: more than 60 million years separate them.", "Myth: all dinosaurs were enormous. Truth: many were the size of chickens.", "Myth: you could clone a dinosaur with DNA from a mosquito in amber. Truth: DNA doesn't last that many millions of years."], ex: { t: "Science telephone", m: "a group of people, a sentence about dinosaurs written on paper", p: ["The first person reads the sentence and whispers it to the next, who passes it on to the end of the line.", "The last person says aloud what they heard. Compare with the paper!", "Did the sentence change? Scientists always go back to the original evidence, the fossils, to check that the story is right."] }, at: "Myth or truth card", m: "paper, colored pencils", p: ["Make two columns: Myth and Truth.", "Write three dinosaur myths and the truth for each one.", "Challenge your family to guess which is which and put the card in the museum."], q: "Have you ever changed your mind after learning something new? About what?" },
es: { h: "A la hora de la merienda, Leo afirmó muy seguro: “¡Los hombres de las cavernas andaban montados en dinosaurios!”. Nina se rió, y el abuelo aprovechó: “Hoy vamos a jugar a cazar mitos. Hasta los científicos se equivocaron feo con los dinosaurios… ¡y corregir los errores es parte de la ciencia!”", t: "Mitos y errores sobre los dinosaurios", f: "A lo largo del tiempo, mucha gente tuvo ideas equivocadas sobre los dinosaurios. Los científicos también se equivocan, pero cuando encuentran nuevas pruebas, corrigen lo que pensaban. Así funciona la ciencia: probando, revisando y aprendiendo siempre.", x: "¡Cuando se descubrió el Iguanodonte, en el siglo XIX, los científicos le pusieron una púa en la nariz! Más tarde descubrieron que la púa iba en el pulgar.", s: ["Mito: los humanos y los dinosaurios gigantes vivieron juntos. Verdad: entre ellos pasaron más de 60 millones de años.", "Mito: todos los dinosaurios eran enormes. Verdad: muchos eran del tamaño de gallinas.", "Mito: se puede clonar un dinosaurio con ADN de un mosquito en ámbar. Verdad: el ADN no dura tantos millones de años."], ex: { t: "Teléfono descompuesto de la ciencia", m: "un grupo de personas, una frase sobre dinosaurios escrita en un papel", p: ["La primera persona lee la frase y se la susurra al oído a la siguiente, que la pasa, hasta el final de la fila.", "La última persona dice en voz alta lo que oyó. ¡Compárenlo con el papel!", "¿La frase cambió? Los científicos siempre vuelven a la prueba original, los fósiles, para comprobar si la historia es correcta."] }, at: "Ficha mito o verdad", m: "papel, lápices de colores", p: ["Haz dos columnas: Mito y Verdad.", "Escribe tres mitos sobre dinosaurios y la verdad de cada uno.", "Desafía a tu familia a adivinar cuál es cuál y pon la ficha en el museo."], q: "¿Alguna vez cambiaste de idea después de aprender algo nuevo? ¿Sobre qué?" } },

{ e: "🐔", art: { b: "🐔", s: ["🦖", "🦶", "🥚", "🔍"], c: ["#5A3A0B", "#E0A03A"] },
pt: { h: "No sítio de um amigo, Leo ficou observando as galinhas. Elas andavam com a cabeça para frente e para trás, ciscavam com pés de três dedos e uma até correu atrás de uma minhoca. “Parecem mini T. rex!”, disse Leo. O vovô riu: “Os cientistas concordam com você!”", t: "A galinha e o T. rex", f: "Os cientistas descobriram que as aves são os parentes vivos mais próximos dos tiranossauros. Restos de proteínas encontrados num osso de T. rex se pareciam mais com as das galinhas e das avestruzes do que com as de jacarés. Pés de três dedos, ossos ocos e ovos em ninhos são heranças dos dinossauros.", x: "Existem hoje mais de 10 mil espécies de aves no mundo, e todas são dinossauros! Quer dizer que existem mais espécies de dinossauros vivos hoje do que de mamíferos.", s: ["As aves andam sobre os dedos dos pés, como os dinossauros carnívoros andavam.", "O “ossinho da sorte” do frango, a fúrcula, também existia no T. rex e no Velocirraptor.", "Alguns cientistas estudam embriões de galinha para entender como os dinossauros se transformaram em aves."], ex: { t: "Caça aos traços de dinossauro", m: "papel, lápis, um parque, uma praça ou um quintal com pássaros", p: ["Observe pássaros por 15 minutos, em silêncio, sem assustar ninguém.", "Marque numa lista quando vir: pés de três dedos, penas, bico, ovos ou ninho, cabeça que balança, corrida em duas pernas.", "Quantos traços de dinossauro você encontrou? Desenhe o pássaro mais “dinossáurico”."] }, at: "Ficha da árvore da família", m: "papel, lápis de cor", p: ["Desenhe uma árvore com um tronco escrito “dinossauros”.", "Nos galhos, desenhe os ramos que viraram T. rex, Velocirraptor, Archaeopteryx e as aves de hoje.", "Desenhe uma galinha no galho mais alto e coloque a ficha no museu."], q: "Qual pássaro do seu dia a dia você vai olhar diferente a partir de hoje?" },
en: { h: "At a friend's farm, Leo watched the chickens. They bobbed their heads back and forth, scratched with three-toed feet and one even chased after a worm. “They look like mini T. rexes!” Leo said. Grandpa laughed: “Scientists agree with you!”", t: "The chicken and the T. rex", f: "Scientists found that birds are the closest living relatives of tyrannosaurs. Bits of protein found in a T. rex bone were more like those of chickens and ostriches than those of alligators. Three-toed feet, hollow bones and eggs in nests are all inherited from dinosaurs.", x: "There are more than 10,000 bird species in the world today, and every one of them is a dinosaur! That means there are more species of living dinosaurs today than of mammals.", s: ["Birds walk on their toes, just as meat-eating dinosaurs did.", "A chicken's wishbone, the furcula, also existed in T. rex and Velociraptor.", "Some scientists study chicken embryos to understand how dinosaurs turned into birds."], ex: { t: "Dinosaur trait hunt", m: "paper, pencil, a park, square or yard with birds", p: ["Watch birds quietly for 15 minutes without scaring them.", "Check off on a list each time you see: three-toed feet, feathers, a beak, eggs or a nest, head bobbing, running on two legs.", "How many dinosaur traits did you find? Draw the most “dinosaur-y” bird."] }, at: "Family tree card", m: "paper, colored pencils", p: ["Draw a tree with a trunk labeled “dinosaurs.”", "On the branches, draw the lines that led to T. rex, Velociraptor, Archaeopteryx and today's birds.", "Draw a chicken on the highest branch and put the card in the museum."], q: "Which everyday bird will you look at differently from now on?" },
es: { h: "En la chacra de un amigo, Leo se quedó observando a las gallinas. Movían la cabeza hacia adelante y hacia atrás, escarbaban con patas de tres dedos y una hasta corrió detrás de una lombriz. “¡Parecen mini T. rex!”, dijo Leo. El abuelo se rió: “¡Los científicos están de acuerdo contigo!”", t: "La gallina y el T. rex", f: "Los científicos descubrieron que las aves son los parientes vivos más cercanos de los tiranosaurios. Restos de proteínas encontrados en un hueso de T. rex se parecían más a los de las gallinas y los avestruces que a los de los yacarés. Las patas de tres dedos, los huesos huecos y los huevos en nidos son herencias de los dinosaurios.", x: "¡Hoy existen más de 10.000 especies de aves en el mundo, y todas son dinosaurios! Quiere decir que hoy hay más especies de dinosaurios vivos que de mamíferos.", s: ["Las aves caminan sobre los dedos de las patas, como caminaban los dinosaurios carnívoros.", "El “hueso de la suerte” del pollo, la fúrcula, también existía en el T. rex y el Velocirraptor.", "Algunos científicos estudian embriones de gallina para entender cómo los dinosaurios se convirtieron en aves."], ex: { t: "Caza de rasgos de dinosaurio", m: "papel, lápiz, un parque, una plaza o un patio con pájaros", p: ["Observa pájaros durante 15 minutos, en silencio, sin asustarlos.", "Marca en una lista cuando veas: patas de tres dedos, plumas, pico, huevos o nido, cabeza que se balancea, carrera en dos patas.", "¿Cuántos rasgos de dinosaurio encontraste? Dibuja el pájaro más “dinosáurico”."] }, at: "Ficha del árbol familiar", m: "papel, lápices de colores", p: ["Dibuja un árbol con un tronco que diga “dinosaurios”.", "En las ramas, dibuja las líneas que llevaron al T. rex, al Velocirraptor, al Archaeopteryx y a las aves de hoy.", "Dibuja una gallina en la rama más alta y pon la ficha en el museo."], q: "¿Qué pájaro de tu día a día vas a mirar distinto desde hoy?" } },

{ e: "🍪", art: { b: "🍪", s: ["⛏️", "🖌️", "🔍", "📓"], c: ["#4E2A0B", "#B0703A"] },
pt: { h: "Nina disse que queria ser paleontóloga quando crescer. O vovô colocou na mesa um prato de biscoitos com gotas de chocolate e uns palitos de dente. “Então hoje é o seu primeiro dia de trabalho”, disse. “Sua missão: tirar todos os fósseis de chocolate sem quebrar o biscoito!”", t: "Como ser paleontólogo", f: "Paleontólogos estudam muito: biologia, geologia, química e até computação. Eles trabalham em escavações ao ar livre, às vezes em desertos e montanhas, e também em laboratórios e museus. No Brasil, há paleontólogos em várias universidades e museus fazendo descobertas importantes.", x: "Muitas descobertas incríveis foram feitas por acaso, por agricultores, operários de obras e até crianças passeando! Se você achar algo parecido com um fóssil, o certo é avisar um museu ou uma universidade.", s: ["Hoje os paleontólogos usam tomografia, como a dos hospitais, para ver dentro dos fósseis sem quebrá-los.", "Uma escavação pode durar várias semanas sob sol forte.", "Paciência, curiosidade e cuidado são as ferramentas mais importantes de um paleontólogo."], ex: { t: "Escavação no biscoito", m: "biscoitos com gotas de chocolate, palitos de dente, um pincel limpo, um prato, papel e lápis", p: ["Coloque um biscoito no prato: ele é a “rocha”, e as gotas de chocolate são os “fósseis”.", "Usando só o palito e o pincel, tente tirar as gotas inteiras, sem quebrar o biscoito.", "Anote quantos fósseis você tirou e quantos quebraram. Depois, pode comer a escavação!"] }, at: "Ficha do meu crachá", m: "cartolina, lápis de cor, barbante", p: ["Faça um crachá de paleontólogo com seu nome, foto ou desenho e a especialidade (ovos, pegadas, pterossauros…).", "Escreva três ferramentas que você levaria numa escavação.", "Pendure o crachá no pescoço e coloque uma cópia no museu."], q: "Que parte do trabalho de paleontólogo você acharia mais legal?" },
en: { h: "Nina said she wanted to be a paleontologist when she grows up. Grandpa set a plate of chocolate chip cookies and some toothpicks on the table. “Then today is your first day on the job,” he said. “Your mission: get all the chocolate fossils out without breaking the cookie!”", t: "How to be a paleontologist", f: "Paleontologists study a lot: biology, geology, chemistry and even computing. They work at outdoor digs, sometimes in deserts and mountains, and also in labs and museums. In Brazil, paleontologists at many universities and museums are making important discoveries.", x: "Many amazing discoveries were made by accident, by farmers, construction workers and even kids out for a walk! If you find something that looks like a fossil, the right thing to do is tell a museum or university.", s: ["Today paleontologists use CT scans, like those in hospitals, to see inside fossils without breaking them.", "A dig can last several weeks under a hot sun.", "Patience, curiosity and care are a paleontologist's most important tools."], ex: { t: "Cookie dig", m: "chocolate chip cookies, toothpicks, a clean paintbrush, a plate, paper and pencil", p: ["Put a cookie on the plate: it's the “rock,” and the chocolate chips are the “fossils.”", "Using only the toothpick and brush, try to get the chips out whole without breaking the cookie.", "Write down how many fossils you removed and how many broke. Then you can eat your dig site!"] }, at: "My badge card", m: "poster board, colored pencils, string", p: ["Make a paleontologist badge with your name, photo or drawing and your specialty (eggs, footprints, pterosaurs…).", "Write three tools you'd take on a dig.", "Hang the badge around your neck and put a copy in the museum."], q: "Which part of a paleontologist's job would you think is coolest?" },
es: { h: "Nina dijo que quería ser paleontóloga cuando fuera grande. El abuelo puso en la mesa un plato de galletitas con chispas de chocolate y unos palillos. “Entonces hoy es tu primer día de trabajo”, dijo. “Tu misión: ¡sacar todos los fósiles de chocolate sin romper la galletita!”", t: "Cómo ser paleontólogo", f: "Los paleontólogos estudian mucho: biología, geología, química y hasta computación. Trabajan en excavaciones al aire libre, a veces en desiertos y montañas, y también en laboratorios y museos. En Sudamérica hay paleontólogos en muchas universidades y museos haciendo descubrimientos importantes.", x: "¡Muchos descubrimientos increíbles se hicieron por casualidad, por agricultores, obreros de la construcción y hasta niños de paseo! Si encuentras algo parecido a un fósil, lo correcto es avisar a un museo o una universidad.", s: ["Hoy los paleontólogos usan tomografías, como las de los hospitales, para ver dentro de los fósiles sin romperlos.", "Una excavación puede durar varias semanas bajo el sol fuerte.", "La paciencia, la curiosidad y el cuidado son las herramientas más importantes de un paleontólogo."], ex: { t: "Excavación en la galletita", m: "galletitas con chispas de chocolate, palillos, un pincel limpio, un plato, papel y lápiz", p: ["Pon una galletita en el plato: es la “roca”, y las chispas de chocolate son los “fósiles”.", "Usando solo el palillo y el pincel, intenta sacar las chispas enteras sin romper la galletita.", "Anota cuántos fósiles sacaste y cuántos se rompieron. ¡Después puedes comerte la excavación!"] }, at: "Ficha de mi credencial", m: "cartulina, lápices de colores, cordel", p: ["Haz una credencial de paleontólogo con tu nombre, foto o dibujo y tu especialidad (huevos, huellas, pterosaurios…).", "Escribe tres herramientas que llevarías a una excavación.", "Cuélgate la credencial al cuello y pon una copia en el museo."], q: "¿Qué parte del trabajo de paleontólogo te parecería más divertida?" } },

{ e: "🎨", art: { b: "🎨", s: ["🦴", "💪", "🖌️", "🦕"], c: ["#3A1B3A", "#9A4A9A"] },
pt: { h: "Leo perguntou como os desenhistas sabiam o formato dos dinossauros, se só sobraram os ossos. O vovô mostrou o trabalho de um paleoartista: primeiro o esqueleto, depois os músculos por cima, depois a pele. “É ciência e arte juntas”, disse. Nina pegou a massinha na hora.", t: "Paleoarte: dando vida aos ossos", f: "Paleoartistas são artistas que trabalham com cientistas para mostrar como os dinossauros eram em vida. Eles estudam o esqueleto, as marcas onde os músculos se prendiam nos ossos e comparam com animais de hoje, como aves e crocodilos, para desenhar com o máximo de verdade.", x: "Os desenhos de dinossauros mudam com as novas descobertas! Antigamente eles eram pintados arrastando a cauda no chão. Hoje sabemos que a cauda ficava levantada, equilibrando o corpo.", s: ["Fósseis de pele e de penas ajudam os artistas a acertar a textura do corpo.", "Muitos detalhes, como as cores e os sons, ainda dependem de muita imaginação.", "Uma boa paleoarte mostra o animal fazendo coisas reais: comendo, cuidando de filhotes, dormindo."], ex: { t: "Músculos de massinha", m: "palitos de dente ou de picolé, massinha de duas cores, um prato", p: ["Monte um “esqueleto” simples de dinossauro com palitos: coluna, pernas e cauda.", "Coloque por cima uma camada de massinha vermelha, como se fossem os músculos, mais grossa nas pernas e no pescoço.", "Cubra com a massinha de outra cor como pele. Viu como o mesmo esqueleto pode ficar magrinho ou fortão?"] }, at: "Ficha de paleoarte", m: "papel, lápis de cor", p: ["Desenhe um dinossauro em três etapas, lado a lado: esqueleto, músculos e corpo completo.", "Coloque-o fazendo algo real: dormindo, bebendo água ou cuidando dos filhotes.", "Coloque a ficha no museu, na galeria de arte."], q: "Se você fosse paleoartista, que cena de dinossauros desenharia?" },
en: { h: "Leo asked how artists knew what dinosaurs looked like if only bones were left. Grandpa showed him a paleoartist's work: first the skeleton, then the muscles on top, then the skin. “It's science and art together,” he said. Nina grabbed the play dough right away.", t: "Paleoart: bringing bones to life", f: "Paleoartists are artists who work with scientists to show what dinosaurs looked like alive. They study the skeleton and the marks where muscles attached to bones, and compare with animals today, like birds and crocodiles, to draw them as accurately as possible.", x: "Dinosaur pictures change with new discoveries! Long ago they were painted dragging their tails on the ground. Today we know the tail was held up, balancing the body.", s: ["Fossilized skin and feathers help artists get body textures right.", "Many details, like colors and sounds, still depend on lots of imagination.", "Good paleoart shows animals doing real things: eating, caring for babies, sleeping."], ex: { t: "Play dough muscles", m: "toothpicks or popsicle sticks, play dough in two colors, a plate", p: ["Build a simple dinosaur “skeleton” with sticks: spine, legs and tail.", "Add a layer of red play dough on top as muscles, thicker on the legs and neck.", "Cover it with the other color as skin. See how the same skeleton can end up skinny or bulky?"] }, at: "Paleoart card", m: "paper, colored pencils", p: ["Draw a dinosaur in three stages, side by side: skeleton, muscles and the complete animal.", "Show it doing something real: sleeping, drinking water or caring for its babies.", "Put the card in the museum's art gallery."], q: "If you were a paleoartist, what dinosaur scene would you draw?" },
es: { h: "Leo preguntó cómo sabían los dibujantes la forma de los dinosaurios, si solo quedaron los huesos. El abuelo le mostró el trabajo de un paleoartista: primero el esqueleto, después los músculos encima, después la piel. “Es ciencia y arte juntos”, dijo. Nina agarró la plastilina enseguida.", t: "Paleoarte: dando vida a los huesos", f: "Los paleoartistas son artistas que trabajan con científicos para mostrar cómo eran los dinosaurios en vida. Estudian el esqueleto, las marcas donde se sujetaban los músculos en los huesos y comparan con animales de hoy, como aves y cocodrilos, para dibujarlos con la mayor verdad posible.", x: "¡Los dibujos de dinosaurios cambian con los nuevos descubrimientos! Antes los pintaban arrastrando la cola por el suelo. Hoy sabemos que la cola estaba levantada, equilibrando el cuerpo.", s: ["Los fósiles de piel y de plumas ayudan a los artistas a acertar con la textura del cuerpo.", "Muchos detalles, como los colores y los sonidos, todavía dependen de mucha imaginación.", "Un buen paleoarte muestra al animal haciendo cosas reales: comiendo, cuidando crías, durmiendo."], ex: { t: "Músculos de plastilina", m: "palillos o palitos de helado, plastilina de dos colores, un plato", p: ["Arma un “esqueleto” simple de dinosaurio con palitos: columna, patas y cola.", "Pon encima una capa de plastilina roja, como si fueran los músculos, más gruesa en las patas y el cuello.", "Cúbrelo con la plastilina de otro color como piel. ¿Viste cómo el mismo esqueleto puede quedar flaquito o fortachón?"] }, at: "Ficha de paleoarte", m: "papel, lápices de colores", p: ["Dibuja un dinosaurio en tres etapas, una al lado de la otra: esqueleto, músculos y cuerpo completo.", "Muéstralo haciendo algo real: durmiendo, tomando agua o cuidando a sus crías.", "Pon la ficha en el museo, en la galería de arte."], q: "Si fueras paleoartista, ¿qué escena de dinosaurios dibujarías?" } },

{ e: "🏆", art: { b: "🥚", s: ["🦖", "🦕", "🎉", "🏛️"], c: ["#2E4A1E", "#D4B02C"] },
pt: { h: "Na última noite, o Museu dos Dinossauros estava cheio de fichas, desenhos e esqueletos de cotonete. O vovô convidou a família toda para a inauguração. Mas antes, uma surpresa: ovos misteriosos que só iam “chocar” com uma poção especial. O Pipoca ficou de guarda, muito curioso.", t: "Inauguração do museu", f: "Em 30 dias, vocês viajaram por mais de 160 milhões de anos: dos primeiros dinossauros do Brasil aos gigantes pescoçudos, do T. rex aos raptores com penas, dos pterossauros ao asteroide, até descobrir que os dinossauros continuam vivos nas aves. E aprenderam como a ciência descobre o passado.", x: "Todo ano, os cientistas descrevem dezenas de novas espécies de dinossauros! Ainda há muito para descobrir, e quem sabe uma delas não será encontrada por você?", s: ["Fósseis são pistas que a Terra guardou para a gente ler.", "A ciência muda e melhora com cada descoberta nova.", "O Brasil tem um tesouro enorme de fósseis esperando para ser estudado."], ex: { t: "Ovos de dinossauro que chocam", m: "bicarbonato de sódio, água, um dinossauro pequeno de brinquedo, vinagre, uma bandeja, corante (opcional)", p: ["Misture bicarbonato com um pouquinho de água (e corante) até formar uma massa que dá para moldar.", "Envolva o dinossauro com a massa, formando um ovo, e deixe secar ou congelar por algumas horas.", "Na bandeja, despeje vinagre devagar sobre o ovo: ele borbulha, se desmancha e o filhote aparece!"] }, at: "Inauguração do museu", m: "o seu museu, cartolina, lápis de cor", p: ["Faça convites para a família visitar o Museu dos Dinossauros.", "Seja o guia: apresente as fichas e conte as curiosidades de que mais gostou.", "Entregue a cada visitante um ingresso feito por você e comemore a missão cumprida!"], q: "De tudo o que você descobriu sobre dinossauros, o que mais te impressionou?" },
en: { h: "On the last night, the Dinosaur Museum was full of cards, drawings and cotton swab skeletons. Grandpa invited the whole family to the grand opening. But first, a surprise: mysterious eggs that would only “hatch” with a special potion. Popcorn stood guard, very curious.", t: "The museum's grand opening", f: "In 30 days, you traveled through more than 160 million years: from Brazil's first dinosaurs to the long-necked giants, from T. rex to feathered raptors, from pterosaurs to the asteroid, all the way to discovering that dinosaurs are still alive as birds. And you learned how science uncovers the past.", x: "Every year, scientists describe dozens of new dinosaur species! There's still so much to discover, and who knows, maybe you'll find one!", s: ["Fossils are clues the Earth saved for us to read.", "Science changes and improves with every new discovery.", "The world still holds enormous fossil treasures waiting to be studied."], ex: { t: "Hatching dinosaur eggs", m: "baking soda, water, a small toy dinosaur, vinegar, a tray, food coloring (optional)", p: ["Mix baking soda with a little water (and coloring) until it forms a dough you can shape.", "Wrap the dough around the dinosaur to form an egg, and let it dry or freeze for a few hours.", "On the tray, slowly pour vinegar over the egg: it fizzes, crumbles and the baby appears!"] }, at: "Museum opening", m: "your museum, poster board, colored pencils", p: ["Make invitations for your family to visit the Dinosaur Museum.", "Be the guide: present your cards and share the facts you liked best.", "Give each visitor a ticket you made and celebrate a mission accomplished!"], q: "Of everything you discovered about dinosaurs, what impressed you most?" },
es: { h: "En la última noche, el Museo de los Dinosaurios estaba lleno de fichas, dibujos y esqueletos de hisopos. El abuelo invitó a toda la familia a la inauguración. Pero antes, una sorpresa: huevos misteriosos que solo iban a “eclosionar” con una poción especial. Palomita hizo guardia, muy curioso.", t: "Inauguración del museo", f: "En 30 días viajaron por más de 160 millones de años: de los primeros dinosaurios de Sudamérica a los gigantes cuellilargos, del T. rex a los raptores con plumas, de los pterosaurios al asteroide, hasta descubrir que los dinosaurios siguen vivos en las aves. Y aprendieron cómo la ciencia descubre el pasado.", x: "¡Cada año los científicos describen decenas de especies nuevas de dinosaurios! Todavía queda mucho por descubrir, ¿y quién sabe si una no la encontrarás tú?", s: ["Los fósiles son pistas que la Tierra guardó para que las leamos.", "La ciencia cambia y mejora con cada descubrimiento nuevo.", "Sudamérica tiene un enorme tesoro de fósiles esperando ser estudiado."], ex: { t: "Huevos de dinosaurio que eclosionan", m: "bicarbonato de sodio, agua, un dinosaurio pequeño de juguete, vinagre, una bandeja, colorante (opcional)", p: ["Mezcla bicarbonato con un poquito de agua (y colorante) hasta formar una masa que se pueda moldear.", "Envuelve el dinosaurio con la masa formando un huevo, y déjalo secar o congelar unas horas.", "En la bandeja, echa vinagre despacio sobre el huevo: ¡burbujea, se deshace y aparece la cría!"] }, at: "Inauguración del museo", m: "tu museo, cartulina, lápices de colores", p: ["Haz invitaciones para que tu familia visite el Museo de los Dinosaurios.", "Sé el guía: presenta las fichas y cuenta las curiosidades que más te gustaron.", "¡Entrega a cada visitante una entrada hecha por ti y celebren la misión cumplida!"], q: "De todo lo que descubriste sobre los dinosaurios, ¿qué fue lo que más te impresionó?" } },
];
